{
  "format": "craftmine.capabilities/1",
  "runtime": "craftmine-web/5",
  "entry": {
    "export": "step",
    "signature": "async step({frame, params, state}) => {state, commands}",
    "module": "ES 模块，必须导出 step"
  },
  "events": [
    {
      "type": "start",
      "payload": {},
      "note": "模块装载时一次，用来注册物品和面板"
    },
    {
      "type": "tick",
      "payload": {
        "dt": "秒"
      },
      "note": "每帧一次，返回的 commands 最多 32 条"
    },
    {
      "type": "interact",
      "payload": {
        "targetId": "对象 ID"
      },
      "note": "玩家按 E 指向声明过的目标"
    },
    {
      "type": "contact",
      "payload": {
        "targetId": "对象 ID"
      },
      "note": "玩家接触声明过的目标"
    },
    {
      "type": "attack",
      "payload": {
        "targetId": "对象 ID"
      },
      "note": "玩家攻击命中声明过的目标"
    },
    {
      "type": "land",
      "payload": {
        "targetId": "对象 ID"
      },
      "note": "玩家落在声明过的目标上"
    },
    {
      "type": "key",
      "payload": {
        "code": "keys 中声明过的按键代码"
      },
      "note": "只有模块在 keys 里声明过的按键才会触发；不要读 frame.keys"
    }
  ],
  "keys": [
    "KeyB",
    "KeyC",
    "KeyG",
    "KeyH",
    "KeyI",
    "KeyJ",
    "KeyK",
    "KeyL",
    "KeyM",
    "KeyN",
    "KeyO",
    "KeyP",
    "KeyQ",
    "KeyU",
    "KeyV",
    "KeyX",
    "KeyY",
    "KeyZ",
    "Digit3",
    "Digit4",
    "Digit5",
    "Digit6",
    "Digit7",
    "Digit8",
    "Digit9"
  ],
  "permissions": [
    "objects.write",
    "player.motion",
    "hud.message",
    "inventory.write",
    "audio.play",
    "targets.write",
    "resources.write",
    "health.write"
  ],
  "capabilities": [
    "inventory.read@1",
    "inventory.items@1",
    "hud.panel@1"
  ],
  "requires": [
    "health@1",
    "ranged@1",
    "melee@1",
    "resource@1"
  ],
  "commands": [
