      "type": "object.patch",
      "permission": "objects.write",
      "scope": "声明过的 targets 里的对象",
      "fields": [
        {
          "name": "id",
          "description": "对象 ID"
        },
        {
          "name": "position",
          "description": "{x,y,z} 或 null；整项省略等同 null（保留原值）"
        },
        {
          "name": "visible",
          "description": "boolean 或 null"
        },
        {
          "name": "solid",
          "description": "boolean 或 null"
        },
        {
          "name": "color",
          "description": "'#RRGGBB' 或 null"
        },
        {
          "name": "yaw",
          "description": "null 或 0/90/180/270"
        },
        {
          "name": "duration",
          "description": "可选 0..5 秒，平滑移动"
        }
      ],
      "quota": "每步最多 32 条命令",
      "example": "{type:'object.patch',id:'door-1',visible:false}",
      "note": "visible:true 不会让已死亡的目标重新生效，复活必须用 target.revive"
    },
    {
      "type": "player.impulse",
      "permission": "player.motion",
      "scope": "当前玩家",
      "fields": [
        {
          "name": "velocity",
          "description": "{x,y,z}，每轴 -18..18"
        }
      ],
      "quota": "每步最多 1 条",
      "example": "{type:'player.impulse',velocity:{x:0,y:8,z:0}}"
    },
    {
      "type": "hud.message",
      "permission": "hud.message",
      "scope": "当前玩家",
      "fields": [
        {
          "name": "text",
          "description": "最多 160 字纯文本"
        },
        {
          "name": "tone",
          "description": "可选 'info' | 'warn' | 'success'"
        },
        {
          "name": "duration",
          "description": "可选 1000..10000 毫秒"
        }
      ],
      "quota": "每步最多 1 条",
      "example": "{type:'hud.message',text:'门开了',tone:'success'}"
    },
    {
      "type": "audio.play",
      "permission": "audio.play",
      "scope": "当前玩家",
